'use strict';
(function(){
const esc=I.esc;
const phaseNames={morning:'10 h · Le cap de la semaine',evening:'17 h · La soirée',midnight:'Minuit · Le bilan',month:'Retour du show · Le prochain cap'};
let shown=null;
function summaryHTML(items){return items?.length?`<ul class="week-summary">${items.map(item=>`<li>${item.songId?'':'<span aria-hidden="true">↔</span>'}<span>${I.songText(state,item.text)}${item.songId?I.songStats(M.song(state,item.songId)):''}</span></li>`).join('')}</ul>`:'<p class="tiny">Un moment calme : les habitudes et les liens ont continué à se construire.</p>';}
function closeAndRun(){dialogWasRunning=true;closeDialog();}
function skip(){window.MaisonNightUI.begin();}
function songLine(id){const song=M.song(state,id);return song?`<div class="week-song"><strong class="song-heading">${I.songTitle(song)}</strong>${I.songStats(song)}</div>`:'';}
function choiceText(c,e){const song=M.song(state,c.songId),person=state.people.find(p=>p.id===e.personId);return ({write:'Avancer les compositions de chacun.',rehearse:song?(song.adopted?'Répéter à deux ou plus pour préparer le show.':'Essayer si plus de la moitié accepte, puis voter pour l’adopter.'):'Pratiquer son instrument, sans préparer de chanson.',talk:'Discuter et renforcer les liens.',party:'Se rapprocher en dépensant de l’énergie.',jam:'Jammer ensemble et faire naître des idées.',quiet:'Se reposer et récupérer de l’énergie.',tomorrow:song?`${person?.name||'L’auteur'} dort, puis reprend l’écriture demain.`:'Dormir, puis proposer une matinée de pratique.',sleep:'Tout le monde dort jusqu’à 8 h.',nightwrite:`${person?.name||'L’auteur'} écrit; les autres dorment. Fatigue demain.`,afterparty:'Les volontaires veillent et récupèrent moins.', 'month-write':'Favoriser la composition pendant les deux prochains mois.', 'month-practice':'Favoriser la pratique pendant les deux prochains mois.', 'month-social':'Favoriser les relations pendant les deux prochains mois.'})[c.id]||c.text;}
function showResult(o){
 const responses=[...o.refused.map(p=>({...p,yes:false})),...o.accepted.map(p=>({...p,yes:true}))];
 openDialog(`<section class="week-result-sheet" data-dialog-layout="single"><span class="eyebrow">✓ CHOIX ENREGISTRÉ · EN PAUSE</span><h2>${esc(o.title)}</h2>${songLine(o.songId)}<p class="week-choice-note">${o.accepted.length} volontaire(s) · ${o.refused.length} refus</p>${o.trialInsufficient?`<p class="hint">${esc(o.reason)}</p>`:''}<div class="week-responses"><h3>Leur réponse</h3>${responses.map(r=>{const p=state.people.find(p=>p.id===r.id),waiting=r.yes&&p?.intent&&!p.intent.applied;return `<article class="week-response ${r.yes?'accepted':'declined'}">${I.portrait(p)}<div><strong>${I.icons[p?.instrument]||'♪'} ${esc(p?.name||r.id)}</strong><span class="response-label">${r.yes?(waiting?'◷ En attente':'✓ Accepte'):'× Refuse'}</span><p>${esc(r.reason)}</p></div></article>`;}).join('')}</div><button id="continueWeek" class="primary">Observer la maison →</button></section>`);
 $('#continueWeek').onclick=closeAndRun;
}
function showEvent(){if(state.journey?.encounter?.phase==='decision'){window.MaisonJourneyUI?.open();return;}
 const e=state.calendar.pending;if(!e)return;shown=e.id;
 const options=W.choices(state,e),until=e.phase==='morning'?'Jusqu’à 17 h':e.phase==='evening'?'Jusqu’à minuit':e.phase==='month'?'Pour les deux prochains mois':'Avant de se coucher';
 openDialog(`<section class="week-choice-sheet" data-dialog-layout="single"><span class="eyebrow">SEMAINE ${e.week} · ${phaseNames[e.phase]} · EN PAUSE</span><h2>${esc(e.title)}</h2><p class="week-choice-note">${until} · Chacun peut accepter ou refuser.</p>${['midnight','month'].includes(e.phase)?`<div class="week-brief"><strong>${e.phase==='month'?'Le souvenir du show':'Ce qui s’est passé aujourd’hui'}</strong>${summaryHTML(e.summary?.slice(0,2))}</div>`:''}<div class="event-cards calendar-cards ${options.length===4?'four-cards':''}">${options.map((c,i)=>`<button type="button" class="event-card" data-week-choice="${c.id}"><span class="event-card-number">0${i+1}</span><strong>${esc(c.title)}</strong><p>${esc(choiceText(c,e))}</p>${songLine(c.songId)}<span class="event-card-arrow">${c.sleep?'Se coucher':'Choisir'} ↗</span></button>`).join('')}</div></section>`,()=>{if(state.calendar.pending)dialogWasRunning=false;});
 let chosen=false;
 $('#dialogContent').querySelectorAll('[data-week-choice]').forEach(b=>b.onclick=()=>{
  if(chosen||state.calendar.pending?.id!==e.id)return;
  const o=W.choose(state,b.dataset.weekChoice);if(!o)return;chosen=true;
  save();if(W.isNight(state)){window.MaisonNightUI.begin(o);}else{showResult(o);render();}
 });
}
function showWake(review=false){const wake=review?state.calendar.lastWake:state.calendar.wake;if(!wake)return;shown='wake-'+wake.tick;openDialog(`<span class="eyebrow">SEMAINE ${wake.week} · 8 H · ${review?'SOUVENIR DE LA NUIT':'LE RÉVEIL'}</span><h2>La maison rouvre les yeux.</h2><p>Voici ce qui s’est réellement passé pendant la nuit.</p><div class="wake-people">${wake.people.map(r=>{const p=state.people.find(p=>p.id===r.id);return `<div class="wake-person ${r.tired?'tired':''}">${I.portrait(p)}<div><strong>${I.icons[p?.instrument]||'♪'} ${esc(p?.name||r.id)}</strong><span class="wake-state">${r.tired?'☾ Fatigué':'☀ Reposé'}</span><p>${r.sleepHours} h de sommeil${r.awakeHours?' · '+r.awakeHours+' h éveillé':''}<br>Énergie ${r.energy}/100 <b>(${r.delta>=0?'+':''}${r.delta})</b></p>${p?.intent&&p.intent.until>state.tick?`<small>↗ ${esc(p.intent.label)}</small>`:''}</div></div>`;}).join('')}</div><div class="day-review"><strong>Les traces de la nuit</strong>${summaryHTML(wake.summary)}</div><p class="tiny">Une journée représente une semaine. ${globalThis.MaisonShows?.busy(state)?'Aujourd’hui, préparation du show : café à 9 h, départ ensemble à 11 h.':'Le prochain choix arrive à 10 h.'}</p><button id="wakeContinue" class="primary">${review?'Retour à la maison':'Commencer la semaine'} →</button>`,()=>{if(!review){W.acknowledgeWake(state);save();renderPanel();}});$('#wakeContinue').onclick=()=>{if(!review){W.acknowledgeWake(state);save();}closeAndRun();};}
function maybeShow(){if(state.journey?.encounter?.phase==='decision')return false;if(window.homeOpen)return false;if($('#dialog').open||globalThis.MaisonShows?.blocking(state))return false;const c=state.calendar;if(c.wake&&shown!=='wake-'+c.wake.tick){showWake();save();return true;}if(c.pending&&shown!==c.pending.id){showEvent();save();return true;}return false;}
function showPending(){if(state.calendar.wake)showWake();else if(state.calendar.pending)showEvent();}
function history(){openDialog(`<span class="eyebrow">LE FIL DES SEMAINES</span><h2>Les directions choisies.</h2><div class="moment-history">${state.calendar.history.length?state.calendar.history.map(e=>`<article class="history-row"><span>Semaine ${e.week} · ${phaseNames[e.phase]}</span><strong>${esc(e.title)}</strong><small>${e.accepted.length} volontaire(s) · ${e.refused.length} refus</small></article>`).join(''):'<p>Le premier rendez-vous arrive à 10 h.</p>'}</div>`);}
function renderPanel(){const c=state.calendar,away=!!globalThis.MaisonShows?.busy(state),night=W.isNight(state),pending=c.pending,curWeek=W.week(state),active=c.focus&&c.focus.until>state.tick;const next=c.nextAt%1440===600?'10 h':c.nextAt%1440===1020?'17 h':'minuit';const heading=away?globalThis.MaisonShows.activity(state):pending?phaseNames[pending.phase]:c.wake?'Le réveil':night?'Nuit accélérée · ×32':active?c.focus.label||'Repos':'Prochain choix · '+next;$('#weekPanel').innerHTML=`<div class="week-panel-top"><div><span class="eyebrow">${pending||c.wake?'À TOI DE JOUER':'LE RYTHME DE LA MAISON'}</span><strong>${esc(heading)}</strong></div><div class="week-panel-actions">${pending||c.wake?'<button id="openWeek" class="primary">'+(c.wake?'Bilan':'Décider')+' ↗</button>':night&&!away?'<span class="night-speed">☾ Jusqu’à 8 h</span>':''}<button id="weekHistory" class="quiet" title="Directions choisies" aria-label="Directions choisies">↺</button>${c.lastWake?'<button id="lastWake" class="quiet" title="Dernière nuit" aria-label="Dernière nuit">☾</button>':''}</div></div><div class="week-timeline">${away?'<div class="show-day-plan"><span>8 h · Préparation</span><span>9 h · Café</span><span>11 h · Départ</span><span>22 h · Retour</span></div>':['morning','evening','midnight'].map((phase,i)=>{const done=c.history.some(e=>e.week===curWeek&&e.phase===phase),now=pending?.phase===phase;return `<div class="week-stop ${done?'done':now?'current':''}"><span>${done?'✓':now?'●':'○'}</span><b>${['10 h','17 h','Minuit'][i]}</b></div>`;}).join('')}${away?'':`<div class="week-stop ${night?'current':''}" title="Sommeil de minuit à 8 h"><span>☾</span><b>8 h</b></div>`}</div>`;if($('#openWeek'))$('#openWeek').onclick=showPending;if($('#skipNight'))$('#skipNight').onclick=skip;$('#weekHistory').onclick=history;if($('#lastWake'))$('#lastWake').onclick=()=>showWake(true);$('#map').classList.toggle('night-map',night);$('#map').setAttribute('data-light',H.lightPhase(W.minute(state)));}
function renderWeek(){renderPanel();maybeShow();}
window.MaisonWeeksUI={render:renderWeek,maybeShow,showPending,resetView:()=>{shown=null;}};renderWeek();
})();
